import { BaseEvent } from '@progress/kendo-react-common';
import { CitationSource } from './interfaces/CitationSource';
import { ToolCallActionType } from './interfaces/ToolCallActionType';
import { CheckpointState } from './interfaces/CheckpointState';
/**
 * The arguments for the `onExpandedChange` event of the internal `@hidden` `AgentStep`
 * component shared by `Reasoning`, `ChainOfThought`, and `ToolCall`.
 *
 * @hidden
 */
export interface AgentStepExpandedChangeEvent extends BaseEvent<HTMLButtonElement> {
    /**
     * The new expanded state of the step component.
     * `true` means the component is now expanded; `false` means it is now collapsed.
     */
    expanded: boolean;
}
/**
 * The arguments for the `onExpandedChange` event of the `Reasoning` component.
 */
export interface ReasoningExpandedChangeEvent extends BaseEvent<HTMLButtonElement> {
    /** The new expanded state of the component. */
    expanded: boolean;
}
/**
 * The arguments for the `onExpandedChange` event of the `ChainOfThought` component.
 */
export interface ChainOfThoughtExpandedChangeEvent extends BaseEvent<HTMLButtonElement> {
    /** The new expanded state of the component. */
    expanded: boolean;
}
/**
 * The arguments for the `onExpandedChange` event of the `ToolCall` component.
 */
export interface ToolCallExpandedChangeEvent extends BaseEvent<HTMLButtonElement> {
    /** The new expanded state of the component. */
    expanded: boolean;
}
/**
 * The arguments for the `onAction` event of the `ToolCall` component, fired when
 * the user clicks the Approve or Reject button.
 */
export interface ToolCallActionEvent extends BaseEvent<HTMLButtonElement> {
    /** Which action the user took. */
    action: ToolCallActionType;
}
/**
 * The arguments for the `onAction` event of the `Checkpoint` component, fired
 * when the user activates the current checkpoint action.
 */
export interface CheckpointActionEvent extends BaseEvent<HTMLButtonElement> {
    /** The checkpoint state at the time the action was activated. */
    action: CheckpointState;
}
/**
 * The arguments for the `onOpen` event of the `Citation` component, fired when
 * the citation's resource details are about to be shown.
 */
export interface CitationOpenEvent extends BaseEvent<HTMLDivElement> {
    /** The sources associated with the citation that was activated. */
    sources: CitationSource[];
}
